// Helper functions for exciting card styling
func getCardClasses(shadow string, bordered, clickable bool, maxWidth string) string {
	base := "erp-card animate-fade-in"

	// Shadow classes
	var shadowClass string
	switch shadow {
	case "sm":
		shadowClass = "shadow-sm"
	case "base":
		shadowClass = "shadow"
	case "md":
		shadowClass = "shadow-md"
	case "lg":
		shadowClass = "shadow-lg"
	case "xl":
		shadowClass = "shadow-xl"
	default: // none
		shadowClass = ""
	}

	// Border class
	var borderClass string
	if bordered {
		borderClass = "border border-gray-200 dark:border-gray-700"
	}

	// Clickable class with exciting hover effects
	var clickableClass string
	if clickable {
		clickableClass = "cursor-pointer glow-hover scale-hover"
	}

	// Max width class
	var maxWidthClass string
	if maxWidth != "" {
		maxWidthClass = "max-w-" + maxWidth
	}

	classes := []string{base}
	if shadowClass != "" {
		classes = append(classes, shadowClass)
	}
	if borderClass != "" {
		classes = append(classes, borderClass)
	}
	if clickableClass != "" {
		classes = append(classes, clickableClass)
	}
	if maxWidthClass != "" {
		classes = append(classes, maxWidthClass)
	}

	return strings.Join(classes, " ")
}

func getCardHeaderClasses(padding string) string {
	base := "px-6"

	switch padding {
	case "none":
		return "px-0 pt-0"
	case "sm":
		return base + " pt-4"
	case "lg":
		return base + " pt-8"
	case "xl":
		return base + " pt-10"
	default: // base
		return base + " pt-6"
	}
}

